:root {
  --ink: #061214;
  --deep: #07191b;
  --panel: rgba(8, 22, 24, 0.82);
  --panel-strong: rgba(5, 15, 17, 0.94);
  --line: rgba(213, 239, 232, 0.14);
  --line-gold: rgba(246, 199, 104, 0.4);
  --paper: #f3efe7;
  --white: #fbfffd;
  --muted: #91a5a2;
  --muted-2: #607572;
  --gold: #f6c768;
  --gold-deep: #c89139;
  --coral: #ff7058;
  --coral-deep: #d94c3e;
  --teal: #43ddbe;
  --teal-deep: #158f7e;
  --mint: #b9ffe9;
  --blue: #5bb7ff;
  --danger: #ff4d47;
  --shadow: 0 24px 80px rgba(0, 0, 0, .55);
  --hud-scale: 1;
  --hud-opacity: 1;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; background: var(--ink); color: var(--paper); font-family: 'Outfit', system-ui, -apple-system, sans-serif; overflow: hidden; -webkit-font-smoothing: antialiased; }
body { overscroll-behavior: none; user-select: none; }
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; -webkit-tap-highlight-color: transparent; }
button:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }
h1, h2, h3, h4, p { margin: 0; }
kbd { display: inline-flex; align-items: center; justify-content: center; min-width: 20px; padding: 2px 5px; border: 1px solid rgba(255,255,255,.2); border-radius: 5px; background: rgba(255,255,255,.08); font-family: 'Outfit'; font-size: 10px; font-weight: 600; color: #d9e8e5; box-shadow: 0 1px 0 rgba(255,255,255,.08) inset; }
.hidden { display: none !important; }
#app { position: fixed; inset: 0; overflow: hidden; background: #071416; }
#game-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; cursor: grab; }
#game-canvas:active { cursor: grabbing; }
#world-vignette { position: absolute; inset: 0; pointer-events: none; z-index: 2; background:
  radial-gradient(ellipse at center, transparent 38%, rgba(2, 8, 9, .12) 65%, rgba(2, 8, 9, .62) 110%),
  linear-gradient(180deg, rgba(2, 10, 12, .18), transparent 22%, transparent 75%, rgba(2, 8, 9, .24)); mix-blend-mode: multiply; }
#cinema-bars span { position: fixed; left: 0; right: 0; height: 0; background: #020708; z-index: 40; pointer-events: none; transition: height .7s cubic-bezier(.2,.8,.2,1); }
#cinema-bars span:first-child { top: 0; } #cinema-bars span:last-child { bottom: 0; }
body.cinematic #cinema-bars span { height: 8vh; }
.screen { position: absolute; inset: 0; z-index: 20; display: none; }
.screen.visible { display: block; }

/* ================= BOOT ================= */
#boot-screen { z-index: 60; background:
  radial-gradient(ellipse at 55% 76%, rgba(255, 112, 88, .13), transparent 40%),
  radial-gradient(ellipse at 50% 43%, rgba(67, 221, 190, .07), transparent 34%),
  linear-gradient(180deg, #030c0d 0%, #07191a 55%, #041011 100%); overflow: hidden; }
#boot-screen::before { content: ''; position: absolute; inset: -20%; background: repeating-linear-gradient(0deg, transparent, transparent 3px, rgba(121, 254, 223, .018) 4px); pointer-events: none; }
.boot-noise { position: absolute; inset: 0; opacity: .3; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.28'/%3E%3C/svg%3E"); mix-blend-mode: overlay; }
.boot-center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; animation: bootIn 1.2s cubic-bezier(.2,.8,.2,1) both; }
.boot-mark { width: 82px; height: 82px; display: grid; place-items: center; color: var(--gold); border: 1px solid rgba(246,199,104,.25); border-radius: 50%; box-shadow: 0 0 0 12px rgba(246,199,104,.025), 0 0 70px rgba(246,199,104,.12); margin-bottom: 22px; position: relative; }
.boot-mark::after { content: ''; position: absolute; inset: -26px; border-radius: 50%; border: 1px solid rgba(246,199,104,.09); animation: spin 14s linear infinite; border-top-color: rgba(246,199,104,.5); }
.boot-mark svg { width: 48px; height: 48px; }
.boot-center h1 { font-family: 'Barlow Condensed'; font-weight: 800; font-size: clamp(60px, 9vw, 118px); letter-spacing: .045em; line-height: .84; color: var(--paper); }
.boot-center h1 span { color: var(--gold); font-size: .48em; vertical-align: top; margin-left: 3px; letter-spacing: 0; }
.boot-tagline { margin-top: 18px; font-size: 10px; letter-spacing: .56em; color: var(--muted); font-weight: 500; }
.boot-progress { width: min(330px, 65vw); height: 2px; background: rgba(255,255,255,.1); margin-top: 58px; overflow: hidden; border-radius: 10px; }
.boot-progress i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--gold-deep), var(--gold), #fff2c7); box-shadow: 0 0 16px rgba(246,199,104,.6); transition: width .35s ease; }
.boot-status { font-size: 10px; letter-spacing: .18em; color: var(--muted-2); margin-top: 14px; text-transform: uppercase; }
.boot-footer { position: absolute; left: 42px; right: 42px; bottom: 32px; display: flex; justify-content: space-between; color: rgba(145,165,162,.55); font-size: 9px; letter-spacing: .24em; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes bootIn { from { opacity: 0; transform: translateY(16px) scale(.98); } to { opacity: 1; transform: none; } }

/* ================= EMULATOR ================= */
.emulator { z-index: 50; background: radial-gradient(ellipse at 76% 38%, rgba(28, 96, 88, .22), transparent 48%), linear-gradient(140deg, #061012 0%, #08191b 45%, #041011 100%); }
.emu-scrim { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(3,10,11,.72), transparent 45%, rgba(3,10,11,.3)), linear-gradient(0deg, rgba(3,10,11,.9), transparent 30%); pointer-events: none; }
.emu-scrim::after { content: ''; position: absolute; inset: 0; opacity: .28; background-image: radial-gradient(circle at 2px 2px, rgba(255,255,255,.05) 1px, transparent 0); background-size: 34px 34px; mask-image: linear-gradient(90deg, black, transparent 68%); }
.emu-topbar { position: absolute; top: 0; left: 0; right: 0; height: 78px; padding: 0 42px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,.045); z-index: 2; }
.emu-logo { display: flex; align-items: center; gap: 13px; font-family: 'Barlow Condensed'; font-weight: 700; font-size: 19px; letter-spacing: .14em; color: #e9f4f1; }
.emu-logo svg { width: 27px; height: 27px; color: var(--gold); }
.emu-logo b { color: var(--gold); }
.emu-logo.small { font-size: 16px; }
.emu-logo.small svg { width: 23px; }
.emu-status { display: flex; align-items: center; gap: 20px; font-size: 11px; color: #aec1bd; letter-spacing: .1em; }
.status-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--teal); box-shadow: 0 0 8px var(--teal); }
.emu-net { color: var(--muted); }
.emu-profile { width: 34px; height: 34px; border-radius: 50%; background: linear-gradient(135deg, #2f9c85, #0e4b45); border: 1px solid rgba(255,255,255,.2); font-size: 10px; font-weight: 700; letter-spacing: .05em; color: #d8fff6; }
.emu-layout { position: absolute; top: 78px; left: 0; right: 0; bottom: 48px; display: grid; grid-template-columns: 224px 1fr; z-index: 1; }
.emu-side { padding: 30px 22px; border-right: 1px solid rgba(255,255,255,.045); display: flex; flex-direction: column; gap: 5px; background: linear-gradient(90deg, rgba(3,11,12,.38), transparent); }
.side-item { display: flex; align-items: center; gap: 14px; padding: 12px 14px; border-radius: 10px; color: var(--muted); font-size: 12px; font-weight: 500; text-align: left; transition: .2s; }
.side-item i { font-style: normal; font-size: 15px; width: 19px; color: var(--muted-2); }
.side-item:hover { background: rgba(255,255,255,.04); color: var(--paper); }
.side-item.active { background: rgba(246,199,104,.09); color: var(--gold); box-shadow: inset 2px 0 0 var(--gold); }
.side-item.active i { color: var(--gold); }
.side-bottom { margin-top: auto; }
.side-version { margin: 18px 14px 0; font-size: 8px; letter-spacing: .12em; color: rgba(145,165,162,.38); }
.emu-main { padding: 33px 4.3vw 20px; overflow-y: auto; scrollbar-width: none; }
.emu-main::-webkit-scrollbar { display: none; }
.emu-heading { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 25px; }
.eyebrow { font-size: 9px; letter-spacing: .23em; color: var(--gold); font-weight: 600; text-transform: uppercase; }
.emu-heading h1 { font-weight: 400; font-size: clamp(24px, 2.6vw, 36px); letter-spacing: -.025em; margin-top: 7px; color: #e5eeeb; }
.emu-heading h1 span { color: var(--gold); font-weight: 500; }
.emu-head-meta { display: flex; gap: 8px; padding-bottom: 4px; }
.pill { display: inline-flex; align-items: center; gap: 7px; padding: 6px 10px; border: 1px solid rgba(255,255,255,.09); border-radius: 30px; font-size: 8px; letter-spacing: .13em; font-weight: 600; color: var(--muted); }
.pill i { width: 4px; height: 4px; border-radius: 50%; background: var(--teal); box-shadow: 0 0 6px var(--teal); }
.pill.ghost { color: rgba(145,165,162,.65); }

.game-hero { position: relative; min-height: clamp(360px, 47vh, 510px); border-radius: 18px; overflow: hidden; border: 1px solid rgba(255,255,255,.11); background: #0b2428; box-shadow: 0 24px 60px rgba(0,0,0,.28); isolation: isolate; }
