.hero-city::after { content: ''; position: absolute; inset: 0; background-image: repeating-linear-gradient(90deg, transparent 0 7px, rgba(255,201,113,.35) 7px 8px, transparent 8px 16px); mask-image: linear-gradient(180deg, transparent 28%, black); opacity: .45; }
.hero-sea { position: absolute; left: 0; right: 0; bottom: 0; height: 27%; background: linear-gradient(180deg, #143e46 0%, #0a2c36 40%, #061c25 100%); }
.hero-sea::before { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(176deg, transparent 0 8px, rgba(255,177,119,.13) 9px, transparent 10px 18px); opacity: .6; mask-image: linear-gradient(180deg, black, transparent 80%); }
.hero-sea::after { content: ''; position: absolute; left: 52%; top: 0; width: 26%; height: 32%; background: radial-gradient(ellipse at 50% -20%, rgba(255,225,160,.9), rgba(255,151,98,.22) 40%, transparent 70%); filter: blur(2px); }
.hero-shade { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(3,10,12,.94) 0%, rgba(4,12,14,.68) 36%, rgba(4,15,18,.1) 68%), linear-gradient(0deg, rgba(3,10,11,.75), transparent 40%), linear-gradient(180deg, rgba(2,8,9,.3), transparent 30%); }
.hero-palm { position: absolute; bottom: 20%; width: 3px; height: 36%; background: linear-gradient(0deg, #051014, #16302d); border-radius: 4px; transform: rotate(-6deg); opacity: .9; }
