.hero-meta b { color: var(--gold); font-size: 12px; margin-right: 3px; }
.hero-actions { display: flex; align-items: center; gap: 10px; margin-top: 23px; }
.btn { position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 10px; min-height: 47px; padding: 0 22px; border-radius: 4px; font-size: 11px; font-weight: 600; letter-spacing: .07em; transition: transform .18s ease, background .18s ease, border-color .18s ease; }
