.emu-lower { display: grid; grid-template-columns: 1.45fr 1fr .8fr; gap: 13px; margin-top: 14px; }
.emu-card { border: 1px solid rgba(255,255,255,.075); background: linear-gradient(145deg, rgba(255,255,255,.045), rgba(255,255,255,.015)); border-radius: 11px; padding: 17px 18px; min-height: 150px; backdrop-filter: blur(10px); }
.card-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
