/* ================= GAME MENU ================= */
.game-menu { z-index: 49; background: linear-gradient(100deg, rgba(3,10,12,.92) 0%, rgba(4,13,15,.63) 42%, rgba(4,13,15,.16) 72%, rgba(3,10,12,.52) 100%), linear-gradient(0deg, rgba(3,9,10,.86), transparent 40%); }
.menu-scrim { position: absolute; inset: 0; background: radial-gradient(ellipse at 67% 48%, transparent 0%, rgba(1,7,8,.18) 60%, rgba(1,6,7,.52) 100%); }
