  .side-item span, .side-version { display: none; }
  .emu-main { padding: 22px 20px; }
  .emu-heading h1 { font-size: 25px; }
  .emu-head-meta { display: none; }
  .hero-content { width: 86%; padding: 26px 24px; }
  .hero-copy { max-width: 360px; }
  .hero-side { display: none; }
  .game-hero { min-height: 460px; }
  .hero-meta { gap: 10px; }
  .hero-meta span { font-size: 6.5px; }
  .hero-content h2 { font-size: clamp(58px, 12vw, 88px); }
  .emu-lower { grid-template-columns: 1fr; }
  .community-panel { display: none; }
  .menu-layout { grid-template-columns: 1fr; padding: 3vh 7vw; align-items: center; }
  .menu-side { display: none; }
  .menu-copy { max-width: none; }
  .menu-copy h1 { font-size: clamp(80px, 15vw, 140px); }
  .menu-actions { width: min(440px, 100%); }
  .menu-footer span:first-child { display: none; }
  .map-side { display: none; }
  #big-map { width: 94vw; max-height: 76vh; }
  .pause-body { grid-template-columns: 130px 1fr; }
  .pause-hero { grid-template-columns: 1fr; }
  .pause-hero-art { display: none; }
  .settings-grid { grid-template-columns: 1fr; }
  .objective-panel { width: 270px; }
  .objective-panel p { display: none; }
  .desktop-hint { display: none; }
}
@media (max-width: 700px) {
  .emu-topbar { padding: 0 16px; }
  .emu-logo { font-size: 15px; }
  .emu-status { gap: 10px; }
  .emu-net { display: none; }
  .emu-profile { display: none; }
  .emu-layout { grid-template-columns: 1fr; }
  .emu-side { display: none; }
  .emu-main { padding: 15px 14px 25px; }
  .emu-heading { margin-bottom: 14px; }
  .emu-heading h1 { font-size: 21px; }
  .eyebrow { font-size: 7px; }
  .game-hero { min-height: 520px; }
  .hero-content { width: 100%; padding: 22px 20px; justify-content: flex-end; }
  .hero-badges { margin-bottom: 12px; }
  .hero-content h2 { font-size: 72px; }
  .hero-content h3 { font-size: 16px; letter-spacing: .3em; }
  .hero-copy { font-size: 10px; margin-top: 10px; }
  .hero-meta { margin-top: 10px; }
  .hero-meta span:nth-child(n+3) { display: none; }
  .hero-actions { margin-top: 14px; flex-wrap: wrap; }
  .hero-actions .btn { flex: 1; min-height: 44px; }
  .hero-actions .btn small { display: none; }
  .install-progress { margin-top: 12px; }
  .hero-progress-mini { display: none; }
  .emu-footer { padding: 0 16px; height: 38px; font-size: 6px; }
  .emu-footer span:last-child { display: none; }
  .game-menu { overflow-y: auto; }
  .menu-topbar { height: 63px; padding: 0 17px; }
  .menu-icon-btn { height: 29px; min-width: 34px; font-size: 9px; }
  .menu-layout { position: relative; inset: auto; min-height: 100dvh; padding: 95px 22px 68px; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; }
  .menu-copy h1 { font-size: 94px; }
  .menu-copy h2 { font-size: 17px; letter-spacing: .38em; }
  .menu-tagline { font-size: 12px; margin-top: 13px; }
  .menu-meta { margin-top: 12px; }
  .menu-meta span:nth-child(2) { display: none; }
  .menu-actions { width: 100%; margin-top: 22px; }
  .menu-item { padding: 13px 13px; }
  .mi-text b { font-size: 22px; }
  .menu-footer { height: 43px; padding: 0 18px; }
