  .map-overlay { padding: 15px 14px; }
  .overlay-head h2 { font-size: 24px; }
  .map-legend { display: none; }
  #big-map { width: 100%; max-height: 72vh; }
  .pause-menu { padding: 0; }
  .pause-card { width: 100%; height: 100%; max-height: none; border-radius: 0; border: 0; }
  .pause-head { padding: 15px 16px; }
  .pause-head h1 { font-size: 23px; }
  .pause-profile { display: none; }
  .pause-body { grid-template-columns: 1fr; grid-template-rows: auto 1fr; }
  .pause-tabs { flex-direction: row; overflow-x: auto; padding: 8px 12px; border-right: 0; border-bottom: 1px solid rgba(255,255,255,.08); gap: 4px; scrollbar-width: none; }
  .pause-tabs button { white-space: nowrap; border-left: 0; border-bottom: 2px solid transparent; padding: 9px 11px; }
  .pause-tabs button.active { border-bottom-color: var(--gold); }
