class Game {
  constructor() {
    this.audio = new AudioManager();
    this.missions = MISSIONS;
    this.ui = new UI(this);
    this.settings = this.ui.settings;
    this.state = 'boot';
    this.cinematic = true;
    this.elapsed = 0; ...
