  // ---------------- LOOP ----------------
  startLoop() {
    this.last = performance.now();
    const loop = (now) => {
      requestAnimationFrame(loop);
      const dt = clamp((now - this.last) / 1000, 0, 0.05);
      this.last = now;
      this.update(dt);
      try { this.renderer.render(this.scene, this.camera); } catch (err) { console.error('[Matteo 5] render:', err); }
