  crime(amount) {
    if (this.state !== 'playing') return;
    const before = this.wanted;
    this.wantedHeat = clamp(this.wantedHeat + amount, 0, 6.65);
    this.wanted = clamp(Math.round(this.wantedHeat), 0, 6);
