+    }
+  }
+
+  spawnHostiles(count, center, kind = 'gang', spread = 12, opts = {}) {
+    const names = ['Vini', 'Igor', 'Nina', 'Léo', 'Rui', 'Bia', 'Duda', 'Caio'];
+    const list = [];
