+
+  updateJob(dt) {
+    const job = this.job;
+    if (!job) return;
+    job.elapsed += dt;
+    if (job.elapsed > 300) {
+      this.ui.toast(this.ui.language === 'pt' ? 'Trabalho expirado.' : 'Job expired.', 'warn');
+      this.job = null;
