406:           body+="Run: https://github.com/${GITHUB_REPOSITORY}/actions/runs/${GITHUB_RUN_ID}"$'\n'
407:           body+="SSH URL: \`${SSH_TUNNEL_URL}\`"$'\n'
408:           body+="Host: \`${SSH_HOST}:${SSH_PORT}\`"$'\n\n'
409:           body+=$'Connect while the job is active:\n\n```sh\n'
