526:           # Match issue labels and request hashtags to template stems generically.
527:           template_keys="$(node -e '
528:             const labels = JSON.parse(process.env.LABELS_JSON || "[]");
529:             const tags = [...(process.env.COMMENT_BODY || "").matchAll(/(?:^|[^A-Za-z0-9_])#([A-Za-z0-9_-]+)/g)].map(match => match[1]);
530:             const keys = [...labels, ...tags].map(key => key.trim().toLowerCase());
531:             const platform = keys.includes("mac") ? "mac" : "linux";
532:             process.stdout.write(JSON.stringify([...keys.filter(key => key !== "mac" && key !== "linux"), platform]));
533:           ')"
