Methods:
```js
get voiceAvailable() { return typeof window !== 'undefined' && 'speechSynthesis' in window && typeof SpeechSynthesisUtterance !== 'undefined'; }

setVoiceEnabled(v) { this.voiceEnabled = v; if (!v) this.stopVoice(); }
setVoiceLanguage(lang) { this.voiceLang = lang === 'en' ? 'en-US' : 'pt-BR'; }

loadVoices() {
  if (!this.voiceAvailable) return [];
  this._voices = window.speechSynthesis.getVoices() || [];
  return this._voices;
}

pickVoice(gender, lang) {
  const voices = this._voices.length ? this._voices : this.loadVoices();
  const prefix = lang.slice(0,2).toLowerCase();
  const langVoices = voices.filter(v => v.lang?.toLowerCase().startsWith(prefix));
  const pool = langVoices.length ? langVoices : voices;
  if (!pool.length) return null;
  const femaleNames = /(luciana|maria|francisca|fernanda|joana|camila|helena|alice|isabela|vitoria|vitória|female|mulher|woman|zira|aria|jenny|samantha|karen|moira|tessa|victoria|susan|hazel|libby|sonia|natasha)/i;
  const maleNames = /(daniel|ricardo|felipe|joao|joão|antonio|antônio|bruno|pedro|paulo|male|homem|man|david|mark|alex|fred|tom|guy|george|james|ryan|thomas|william|enrique|jorge|diego|pablo)/i;
  const wanted = gender === 'female' ? femaleNames : maleNames;
  const unwanted = gender === 'female' ? maleNames : femaleNames;
  let candidates = pool.filter(v => wanted.test(v.name));
  if (!candidates.length) candidates = pool.filter(v => !unwanted.test(v.name));
  if (!candidates.length) candidates = pool;
  // prefer local? no, prefer default/network quality? Choose first with pt/en exact.
  return candidates[0] || pool[0] || null;
}

voiceProfile(name = '') {
  const n = String(name).toLowerCase();
  const female = /(luiza|vitória|vitoria|helena|neide|bia|nina|duda|maria|ana|julia|júlia|linda|mãe|mae|garota|moça|moca|senhora|dona|female|woman)/;
  const male = /(carlos|beto|rafa|rui|zeca|vini|igor|léo|leo|caio|paulo|joão|joao|homem|male|man|capitão|capitao|senhor|dr\.|doutor)/;
  if (female.test(n)) return { gender:'female', pitch:1.14, rate:1.02 };
  if (male.test(n)) return { gender:'male', pitch:.78, rate:.98 };
  return { gender:'neutral', pitch:1.0, rate:1.02 };
}

speakLine(text, name = '', opts = {}) {
  if (!this.voiceEnabled || this.muted || !text) return false;
  if (!this.voiceAvailable) return false;
  const synth = window.speechSynthesis;
  try {
    synth.cancel();
    const lang = this.voiceLang || (opts.lang === 'en' ? 'en-US' : 'pt-BR');
    const profile = this.voiceProfile(name);
    const utter = new SpeechSynthesisUtterance(text);
    const voice = this.pickVoice(profile.gender, lang);
    if (voice) { utter.voice = voice; utter.lang = voice.lang || lang; }
    else utter.lang = lang;
    // pitch offset to reinforce gender if chosen voice is unknown
    utter.pitch = clamp(profile.pitch + (opts.pitch || 0), .1, 2);
    utter.rate = clamp((opts.rate || 1) * profile.rate, .6, 1.6);
    utter.volume = clamp((this.voiceVolume ?? .9) * .95, 0, 1);
    // keep speech separate from sfx gain; speechSynthesis has own volume
    synth.speak(utter);
    return true;
  } catch { return false; }
}

stopVoice() { if (this.voiceAvailable) { try { speechSynthesis.cancel(); } catch {} } }
