    tone.frequency.value = gender === 'female' ? 3600 : 3100;
    voiceChain.connect(tone); tone.connect(bus);
    this._nodes.add(voiceChain); this._nodes.add(tone);

    const noise = this._noiseBuffer(ctx);
    let spoken = 0;
