  vibrato.start(start); vibrato.stop(end + .02);
  this._nodes.add(osc); this._nodes.add(vibrato); this._nodes.add(vibratoGain);
  this._nodes.add(env);
  cursor += duration + .032 + Math.random() * .022;
  spoken++;
}

