cat > /tmp/opencode/test-controls.js <<'EOF'
async (page) => {
  const out = {};
  const tap = async (sel) => {
    await page.evaluate((sel) => {
      const el = document.querySelector(sel);
      const r = el.getBoundingClientRect();
      const opts = { bubbles: true, cancelable: true, pointerId: 77, pointerType: 'touch', isPrimary: true, clientX: r.left + r.width / 2, clientY: r.top + r.height / 2 };
      el.dispatchEvent(new PointerEvent('pointerdown', opts));
      el.dispatchEvent(new PointerEvent('pointerup', opts));
    }, sel);
    await page.waitForTimeout(120);
  };
  out.startAmmo = await page.textContent('#ammo');
  await tap('.ps-shoulder.l1');
  out.weapon = await page.textContent('#weapon-name');
  out.ammoAfterSwitch = await page.textContent('#ammo');
  await tap('#touch-l2');
  out.aiming = await page.getAttribute('#crosshair', 'class');
  // hold R2 for ~600ms to fire the SMG
  await page.evaluate(() => {
    const el = document.querySelector('#touch-r2');
    const r = el.getBoundingClientRect();
    el.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, cancelable: true, pointerId: 78, pointerType: 'touch', isPrimary: true, clientX: r.left + r.width/2, clientY: r.top + r.height/2 }));
  });
  await page.waitForTimeout(700);
  await page.evaluate(() => {
    const el = document.querySelector('#touch-r2');
    el.dispatchEvent(new PointerEvent('pointerup', { bubbles: true, cancelable: true, pointerId: 78, pointerType: 'touch', isPrimary: true }));
  });
  out.ammoAfterFire = await page.textContent('#ammo');
  out.toast = await page.textContent('#hud-toast');
  await tap('[data-action="radio"]');
  out.radio = await page.textContent('#radio-station');
  await tap('[data-action="phone"]');
  out.phoneOpen = await page.getAttribute('#phone-overlay', 'class');
  await page.evaluate(() => document.querySelector('#phone-close').click());
  await page.waitForTimeout(150);
  await tap('[data-action="map"]');
  out.mapOpen = await page.getAttribute('#map-overlay', 'class');
  await page.evaluate(() => document.querySelector('#map-close').click());
  await page.waitForTimeout(150);
  await tap('#touch-l3');
  out.sprintClass = await page.getAttribute('#touch-l3', 'class');
  out.sprintToast = await page.textContent('#hud-toast');
  return out;
}
EOF
