        <button data-mission="${i}" ${locked ? 'disabled' : ''}>${done ? (this.language === 'pt' ? 'REJOGAR' : 'REPLAY') : (this.language === 'pt' ? 'INICIAR' : 'START')}</button>
      </div>`;
    }).join('');
    list.querySelectorAll('button[data-mission]').forEach(btn => btn.addEventListener('click', () => {
