/* Contextual world button: floats above cars, doors, people and pickups */
.context-layer { position: absolute; inset: 0; pointer-events: none; overflow: hidden; z-index: 11; }
.context-action {
  position: absolute; left: var(--x, 50%); top: var(--y, 50%);
  transform: translate(-50%, -100%);
  display: none; align-items: center; gap: 7px;
  padding: 7px 11px 7px 7px; border-radius: 5px;
  background: rgba(3,10,11,.9); border: 1px solid rgba(255,255,255,.22);
  box-shadow: 0 8px 26px rgba(0,0,0,.45);
  pointer-events: auto; cursor: pointer; white-space: nowrap;
  animation: contextBlink 1.1s ease-in-out infinite;
}
.context-action.on { display: flex; }
.context-action .ctx-symbol {
  width: 27px; height: 27px; display: grid; place-items: center;
  border-radius: 50%; font-size: 13px; font-weight: 800;
  color: #071416; background: #eef4e9;
}
.context-action .ctx-copy { display: flex; flex-direction: column; align-items: flex-start; line-height: 1.12; }
.context-action b { font-size: 8.5px; letter-spacing: .09em; color: #f7f4e9; }
.context-action small { font-size: 6.5px; letter-spacing: .06em; color: #9fb4ae; }
.context-action[data-icon="triangle"] { border-color: rgba(67,221,190,.65); }
.context-action[data-icon="triangle"] .ctx-symbol { background: #43ddbe; color: #042019; }
.context-action[data-icon="square"] { border-color: rgba(255,139,193,.65); }
.context-action[data-icon="square"] .ctx-symbol { background: #ff8bc1; color: #2a0718; }
.context-action[data-icon="circle"] { border-color: rgba(255,112,88,.65); }
.context-action[data-icon="circle"] .ctx-symbol { background: #ff7058; color: #2a0805; }
.context-action[data-icon="cross"] { border-color: rgba(113,199,255,.65); }
.context-action[data-icon="cross"] .ctx-symbol { background: #71c7ff; color: #041623; }
.context-action[data-icon="dpad"] { border-color: rgba(246,199,104,.65); }
.context-action[data-icon="dpad"] .ctx-symbol { background: #f6c768; color: #231a06; }
@keyframes contextBlink {
  0%, 100% { box-shadow: 0 0 0 0 rgba(246,199,104,0); }
  50% { box-shadow: 0 0 0 4px rgba(246,199,104,.13); }
}

.hunger-row { display: flex; align-items: center; gap: 7px; }
.hunger-row > span { font-size: calc(5.5px * var(--hud-scale)); letter-spacing: .14em; color: var(--muted-2); }
.hunger-bar { width: calc(104px * var(--hud-scale)); height: 2px; background: rgba(255,255,255,.1); }
.hunger-bar i { display: block; height: 100%; width: 100%; background: rgba(255,112,88,.8); transition: width .2s; }
.hunger-row b { font-size: calc(5.5px * var(--hud-scale)); color: rgba(255,190,170,.7); font-weight: 500; }
body.touch .hunger-row, body.force-touch .hunger-row { display: none; }

