    p.y + height,
    p.z + Math.cos(this.camYaw) * horiz
  );
  if (!driving && this.aiming) {
    this._desired.x += Math.cos(this.camYaw) * .55;
    this._desired.z -= Math.sin(this.camYaw) * .55;
